SELECT /*+ MAX_EXECUTION_TIME(5000) */ f.feature_id, CASE WHEN f.feature_name REGEXP '[0-9]{7,}|[0-9]{1,3}[.][0-9]{1,3}[.][0-9]{1,3}[.][0-9]{1,3}|@|://' THEN CONCAT('<已屏蔽:', CHAR_LENGTH(f.feature_name), '字符>') ELSE f.feature_name END AS feature_name_m, f.tool_id, f.third_label, f.feature_valuetype, f.status, CASE WHEN JSON_VALID(f.input_paras) THEN JSON_UNQUOTE(JSON_EXTRACT(f.input_paras, '$.period')) END AS period_v, CASE WHEN JSON_VALID(f.input_paras) THEN JSON_UNQUOTE(JSON_EXTRACT(f.input_paras, '$.counter')) END AS counter_v, CASE WHEN JSON_VALID(f.input_paras) THEN CAST(JSON_EXTRACT(f.input_paras, '$.dimension') AS CHAR) END AS dimension_v, CASE WHEN JSON_VALID(f.input_paras) THEN JSON_UNQUOTE(JSON_EXTRACT(f.input_paras, '$.countValue')) END AS count_value_v, CASE WHEN JSON_VALID(f.input_paras) THEN JSON_UNQUOTE(JSON_EXTRACT(f.input_paras, '$.hasCondition')) END AS has_condition_v, CASE WHEN JSON_VALID(f.input_paras) THEN CHAR_LENGTH(CAST(JSON_EXTRACT(f.input_paras, '$.conditions') AS CHAR)) END AS conditions_len, CHAR_LENGTH(f.input_paras) AS input_paras_len, f.create_time, f.update_time FROM luckyus_iriskcontrolservice.t_rms_engine_third_feature f WHERE f.feature_id IN (SELECT r.feature_id FROM luckyus_iriskcontrolservice.t_rms_engine_rule r JOIN luckyus_iriskcontrolservice.t_rms_engine_strategy_relation x ON x.rule_id = r.rule_id WHERE x.strategy_id LIKE 'strategy_eoHQ6Qs_FRqp')
